urlset:
{%- for page in pages %}

    {{ page.loc }}
    {%- if page.lastmod %}
    {{ page.lastmod.strftime('%Y-%m-%d') }}
    {%- endif %}
    {{ page.changefreq }}
    {{ page.priority }}
    {%- for image in page.images %}

      {{ image.loc }}
      {%- if image.title %}
      {{ image.title }}
      {%- endif %}

    {%- endfor %}

{%- endfor %}
